package website.sung.mangossh.session

import androidx.test.platform.app.InstrumentationRegistry
import java.security.MessageDigest
import java.util.Base64
import kotlinx.coroutines.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Assume.assumeTrue
import org.junit.Test
import website.sung.mangossh.data.keys.SshKeyManager
import website.sung.mangossh.data.vault.StoredAuthentication
import website.sung.mangossh.data.vault.VaultSnapshot
import website.sung.mangossh.domain.ConnectionProfile
import website.sung.mangossh.session.ssh.*

/** Keys and answers are generated by OpenSSH inside the disposable Linux fixture, never checked in. */
class SshMigrationInstrumentedTest {
    private fun host(): String = InstrumentationRegistry.getArguments().getString("fixtureHost") ?: "127.0.0.1"

    private fun port(name: String = "fixturePort"): Int {
        val args = InstrumentationRegistry.getArguments()
        val value = args.getString(name)?.toIntOrNull()
        if (args.getString("requireFixtures") == "true") assertNotNull(value)
        assumeTrue(value != null)
        return value!!
    }
    private suspend fun connect(port: Int): SshConnection = SshConnection(host(), port).also {
        it.connect(10_000) { _, _ -> true }
    }
    private suspend fun text(connection: SshConnection, path: String): String =
        requireNotNull(RemoteFileClient().readTextPreview(connection, path, 64 * 1024)).text
    private suspend fun metadata(connection: SshConnection): JSONObject = connection.openChannel().use { channel ->
        channel.execute("fixture-auth")
        val data = withContext(Dispatchers.IO) { BoundedProtocolReader.bytes(channel.stdout, 64 * 1024) }
        assertEquals(0, withTimeout(5_000) { channel.exitCode() })
        JSONObject(data.toString(Charsets.UTF_8))
    }

    @Test fun opensshAndPemKeysKeepPublicIdentityAndEncryptedBytes() = runBlocking<Unit> {
        val port = port()
        val source = connect(port)
        try {
            assertTrue(source.authenticate("fixture", object : SshCredentials {}))
            val entries = metadata(source).getJSONArray("entries")
            assertEquals(9, entries.length())
            val manager = SshKeyManager()
            for (index in 0 until entries.length()) {
                val entry = entries.getJSONObject(index)
                val expected = entry.getString("public").split(' ')
                val expectedBlob = Base64.getDecoder().decode(expected[1])
                val fingerprint = "SHA256:" + Base64.getEncoder().withoutPadding().encodeToString(
                    MessageDigest.getInstance("SHA-256").digest(expectedBlob))
                for (encrypted in listOf(false, true)) {
                    val pem = text(source, entry.getString(if (encrypted) "encrypted" else "plain"))
                    val passphrase = if (encrypted) entry.getString("passphrase") else null
                    val record = manager.importPrivateKey("fixture", pem, passphrase)
                    assertTrue("Public key identity changed", record.publicKey.split(' ').take(2) == expected)
                    assertTrue("Fingerprint changed", record.fingerprint == fingerprint)
                    assertTrue("Stored private key bytes changed", record.privateKeyPem == pem)
                    assertEquals(encrypted, record.requiresPassphrase)
                    if (encrypted) {
                        assertThrows(Exception::class.java) { manager.decodeKeyPair(record, java.util.UUID.randomUUID().toString()) }
                    }
                    val connection = connect(port)
                    try {
                        assertTrue("Public-key authentication failed for format index $index, encrypted=$encrypted", connection.authenticate("fixture-key", object : SshCredentials {
                            override suspend fun key() = manager.decodeKeyPair(record, passphrase)
                        }))
                    } finally { connection.close() }
                }
            }
            source.keepalive()
        } finally { source.close() }
    }

    /** Stored Ed25519 keys must authenticate with plain, prompted and remembered passphrases. */
    @Test fun ed25519PassphraseModesAuthenticateAndLocalFailuresNeverFallBack() = runBlocking<Unit> {
        val source = connect(port())
        try {
            assertTrue(source.authenticate("fixture", object : SshCredentials {}))
            val entries = metadata(source).getJSONArray("entries")
            val entry = (0 until entries.length()).map(entries::getJSONObject)
                .single { it.getString("public").startsWith("ssh-ed25519 ") }
            val plain = text(source, entry.getString("plain"))
            val encrypted = text(source, entry.getString("encrypted"))
            val passphrase = entry.getString("passphrase")
            val manager = SshKeyManager()
            for ((protected, remember) in listOf(false to false, true to false, true to true)) {
                val key = manager.importPrivateKey("fixture", if (protected) encrypted else plain,
                    passphrase.takeIf { protected }, rememberPassphrase = remember)
                val record = StoredAuthentication(java.util.UUID.randomUUID().toString(), "fixture", keyId = key.id)
                var prompts = 0
                val authentication = SshAuthentication(manager, { _, _, _, fields ->
                    prompts++
                    assertEquals(2, fields.size)
                    assertFalse(fields.first().echo)
                    assertTrue(fields.last().toggle)
                    listOf(passphrase, "")
                }, savePassword = { _, _ -> error("Key authentication must not save a password") },
                    savePassphrase = { _, _ -> error("An unchecked passphrase must not be saved") })
                val connection = connect(port())
                try {
                    assertTrue(authentication.authenticate(connection, "fixture", ConnectionProfile(
                        label = "fixture", hostname = host(), username = "fixture-key", authenticationId = record.id),
                        VaultSnapshot(keys = listOf(key), authentications = listOf(record))))
                    assertEquals(if (protected && !remember) 1 else 0, prompts)
                    connection.keepalive()
                } finally { connection.close() }
            }
            val locked = manager.importPrivateKey("fixture", encrypted, passphrase)
            val record = StoredAuthentication(java.util.UUID.randomUUID().toString(), "fixture", keyId = locked.id)
            for (cancel in listOf(false, true)) {
                var prompts = 0
                val authentication = SshAuthentication(manager, { _, _, _, _ ->
                    prompts++
                    if (cancel) null else listOf(java.util.UUID.randomUUID().toString(), AuthenticationField.TOGGLE_ON)
                }, savePassword = { _, _ -> error("Local failures must not save a password") },
                    savePassphrase = { _, _ -> error("An unverified passphrase must not be saved") })
                val connection = connect(port())
                try {
                    suspend fun authenticate() = authentication.authenticate(connection, "fixture", ConnectionProfile(
                        label = "fixture", hostname = host(), username = "fixture-mixed", authenticationId = record.id),
                        VaultSnapshot(keys = listOf(locked), authentications = listOf(record)))
                    if (cancel) {
                        assertSuspendingThrows(CancellationException::class.java) { authenticate() }
                    } else {
                        val failure = assertSuspendingThrows(SshAuthenticationFailure::class.java) { authenticate() }
                        assertEquals(SshAuthenticationFailure.Category.LOCAL_KEY, failure.category)
                        assertEquals(SshAuthenticationStage.KEY_LOADING, failure.stage)
                    }
                    assertEquals(1, prompts)
                } finally { connection.close() }
            }
        } finally { source.close() }
    }

    @Test fun passwordOtpAndAuthenticationCancellationRemainIsolated() = runBlocking<Unit> {
        val port = port()
        val source = connect(port)
        try {
            assertTrue(source.authenticate("fixture", object : SshCredentials {}))
            val answers = metadata(source)
            for (otp in listOf(false, true)) {
                val connection = connect(port)
                try {
                    assertTrue(connection.authenticate(if (otp) "fixture-otp" else "fixture-password", object : SshCredentials {
                        override suspend fun password() = if (otp) null else answers.getString("password")
                        override suspend fun interactive(name: String, instruction: String, fields: List<SshPromptField>): List<String>? {
                            if (!otp) return null
                            assertEquals(1, fields.size)
                            assertFalse(fields.single().echo)
                            return listOf(answers.getString("otp"))
                        }
                    }))
                } finally { connection.close() }
            }
            val cancelled = connect(port)
            try {
                assertSuspendingThrows(CancellationException::class.java) {
                    cancelled.authenticate("fixture-otp", object : SshCredentials {
                        override suspend fun interactive(name: String, instruction: String, fields: List<SshPromptField>): List<String>? =
                            throw CancellationException("Fixture prompt cancelled")
                    })
                }
                assertSuspendingThrows(SshFailure::class.java) { cancelled.openChannel() }
            } finally { cancelled.close() }
            source.keepalive()
        } finally { source.close() }
    }

    @Test fun profilePolicyHandlesMixedMethodsAndInteractiveFallback() = runBlocking<Unit> {
        val port = port()
        val source = connect(port)
        try {
            assertTrue(source.authenticate("fixture", object : SshCredentials {}))
            val answers = metadata(source)
            for (user in listOf("fixture-mixed", "fixture-otp")) {
                val connection = connect(port)
                var prompts = 0
                val authentication = SshAuthentication(SshKeyManager(), { _, _, _, fields ->
                    assertEquals(if (user == "fixture-otp") 1 else 2, fields.size)
                    prompts++
                    listOf(answers.getString(if (user == "fixture-otp") "otp" else "password")) +
                        if (user == "fixture-otp") emptyList() else listOf("")
                })
                try {
                    assertTrue(authentication.authenticate(connection, "fixture",
                        website.sung.mangossh.domain.ConnectionProfile(
                            label = "fixture", hostname = host(), username = user,
                            authentication = website.sung.mangossh.domain.AuthenticationMethod.AUTOMATIC),
                        website.sung.mangossh.data.vault.VaultSnapshot()))
                    assertEquals(1, prompts)
                } finally { connection.close() }
            }
            val cancelled = connect(port)
            try {
                assertSuspendingThrows(CancellationException::class.java) {
                    SshAuthentication(SshKeyManager(), { _, _, _, _ -> null }).authenticate(cancelled, "fixture",
                        website.sung.mangossh.domain.ConnectionProfile(label = "fixture", hostname = host(),
                            username = "fixture-otp", authentication = website.sung.mangossh.domain.AuthenticationMethod.AUTOMATIC),
                        website.sung.mangossh.data.vault.VaultSnapshot())
                }
                assertSuspendingThrows(SshFailure::class.java) { cancelled.openChannel() }
            } finally { cancelled.close() }
        } finally { source.close() }
    }

    @Test fun unifiedAuthenticationPrefersTheKeyAndUsesSavedPasswordAfterKeyRejection() = runBlocking<Unit> {
        val source = connect(port())
        try {
            assertTrue(source.authenticate("fixture", object : SshCredentials {}))
            val answers = metadata(source)
            val entries = answers.getJSONArray("entries")
            val entry = entries.getJSONObject(entries.length() - 1)
            val manager = SshKeyManager()
            val accepted = manager.importPrivateKey("fixture", text(source, entry.getString("plain")))
            val rejected = manager.generateEd25519("fixture")
            for (key in listOf(accepted, rejected)) {
                val record = StoredAuthentication("fixture-auth", "fixture", if (key == accepted)
                    java.util.UUID.randomUUID().toString() else answers.getString("password"), key.id)
                val connection = connect(port())
                try {
                    val auth = SshAuthentication(manager, { _, _, _, _ -> error("Configured credentials must not prompt") },
                        savePassword = { _, _ -> error("Existing credentials must not be saved again") })
                    assertTrue(auth.authenticate(connection, "fixture", ConnectionProfile(label = "fixture", hostname = host(),
                        username = "fixture-mixed", authenticationId = record.id),
                        VaultSnapshot(keys = listOf(key), authentications = listOf(record))))
                    connection.keepalive()
                } finally { connection.close() }
            }
        } finally { source.close() }
    }

    @Test fun rejectedRememberedInputFallsBackToManualInteractiveWithoutSavingTheWrongPassword() = runBlocking<Unit> {
        val source = connect(port())
        try {
            assertTrue(source.authenticate("fixture", object : SshCredentials {}))
            val answers = metadata(source)
            val manager = SshKeyManager()
            val key = manager.generateEd25519("fixture")
            val record = StoredAuthentication("fixture-auth", "fixture", keyId = key.id)
            var prompts = 0
            val auth = SshAuthentication(manager, { _, _, _, fields ->
                prompts++
                if (prompts == 1) {
                    assertEquals(2, fields.size)
                    assertTrue(fields.last().toggle)
                    assertFalse(fields.last().initiallyChecked)
                    listOf(java.util.UUID.randomUUID().toString(), AuthenticationField.TOGGLE_ON)
                } else {
                    assertEquals(1, fields.size)
                    assertFalse(fields.single().toggle)
                    listOf(answers.getString("otp"))
                }
            }, savePassword = { _, _ -> error("A rejected password must never be saved") })
            val connection = connect(port())
            try {
                assertTrue(auth.authenticate(connection, "fixture", ConnectionProfile(label = "fixture", hostname = host(),
                    username = "fixture-mixed", authenticationId = record.id),
                    VaultSnapshot(keys = listOf(key), authentications = listOf(record))))
                assertEquals(2, prompts)
                connection.keepalive()
            } finally { connection.close() }
        } finally { source.close() }
    }

    @Test fun cancellingPasswordFallbackAfterKeyRejectionClosesTheTransport() = runBlocking<Unit> {
        val manager = SshKeyManager()
        val key = manager.generateEd25519("fixture")
        val record = StoredAuthentication("fixture-auth", "fixture", keyId = key.id)
        var prompts = 0
        val connection = connect(port())
        try {
            assertSuspendingThrows(CancellationException::class.java) {
                SshAuthentication(manager, { _, _, _, fields -> prompts++; assertEquals(2, fields.size); null })
                    .authenticate(connection, "fixture", ConnectionProfile(label = "fixture", hostname = host(),
                        username = "fixture-mixed", authenticationId = record.id),
                        VaultSnapshot(keys = listOf(key), authentications = listOf(record)))
            }
            assertEquals(1, prompts)
            assertSuspendingThrows(SshFailure::class.java) { connection.openChannel() }
        } finally { connection.close() }
    }

    @Test fun changedHostKeyIsRejectedAndNormalExitDrainsBothStreams() = runBlocking<Unit> {
        var trusted: ByteArray? = null
        val first = SshConnection(host(), port())
        try {
            first.connect(10_000) { _, blob -> trusted = blob.copyOf(); true }
            assertTrue(first.authenticate("fixture", object : SshCredentials {}))
            first.openChannel().use { channel ->
                first.enableAgent(object : SshAgent {
                    override fun identities() = emptyList<SshAgentIdentity>()
                    override fun keyForSignature(publicKey: ByteArray): java.security.KeyPair? = null
                })
                assertFalse(channel.requestAgentForwarding())
                channel.pty("xterm-256color", 80, 24)
                channel.resize(100, 36)
                channel.execute("fixture-output")
                val stdout = async(Dispatchers.IO) { channel.stdout.readBytes().size }
                val stderr = async(Dispatchers.IO) { channel.stderr.readBytes().size }
                withTimeout(15_000) {
                    assertEquals(512 * 1024, stdout.await())
                    assertEquals(256 * 1024, stderr.await())
                    assertEquals(0, channel.exitCode())
                }
            }
            first.keepalive()
            val changed = SshConnection(host(), port("fixtureFallbackPort"))
            try {
                val failure = assertSuspendingThrows(SshFailure::class.java) {
                    changed.connect(10_000) { _, blob -> blob.contentEquals(requireNotNull(trusted)) }
                }
                assertEquals(SshFailure.Category.HOST_KEY, failure.category)
            } finally { changed.close() }
        } finally { first.close() }
    }
}
